{"content": "1|// Parser for `ofxPropsBySet.h`, implemented per ./INSTRUCTIONS.md.
2|//
3|// The grammar mirrors the `Structure` schema in ../types.ts one-to-one: every
4|// element of the expected structure corresponds to exactly one parser rule,
5|// and the rules appear in exactly the order the structure tuple prescribes.
6|// Anything the header adds, removes, or reorders therefore fails the parse.
7|// Unlike `ofxPropsMetadata.h`, almost every region of this header contributes
8|// to the result, so nearly everything is parsed structurally; only the body
9|// of `struct Prop` (whose contents are irrelevant) is consumed through a
10|// bracket-delimited "soup" rule that is still strict about its surroundings.
11|
12|import { createToken, CstParser, EOF, Lexer } from "chevrotain";
13|import type { TokenType } from "chevrotain";
14|import {
15|  fail,
16|  Include,
17|  lexingError,
18|  makeHeaderLexer,
19|  parseCppString,
20|  parsingError,
21|  PragmaOnce,
22|  toInt,
23|} from "../../common-by-llms/mod.ts";
24|import type { LexIssue, ParseIssue } from "../../common-by-llms/mod.ts";
25|import type { FinalResult, Prop, Result, Structure } from "../types.ts";
26|
27|// ---------------------------------------------------------------------------
28|// Tokens
29|// ---------------------------------------------------------------------------
30|
31|// --- token categories -------------------------------------------------------
32|// The only ignored region is `struct Prop`'s body, so a single category
33|// suffices: "any token except a brace" may appear inside it. Structural
34|// keywords and fixed names (e.g. `namespace`, `prop_sets`) deliberately carry
35|// no category, so their appearance inside the body is a parse error.
36|
37|const AnyExceptBrace = createToken({
38|  name: "AnyExceptBrace",
39|  pattern: Lexer.NA,
40|});
41|
42|// --- keywords ---------------------------------------------------------------
43|
44|const NamespaceKW = createToken({
45|  name: "NamespaceKW",
46|  pattern: /namespace\b/,
47|});
48|const StructKW = createToken({ name: "StructKW", pattern: /struct\b/ });
49|const StaticAssertKW = createToken({
50|  name: "StaticAssertKW",
51|  pattern: /static_assert\b/,
52|});
53|const StaticKW = createToken({ name: "StaticKW", pattern: /static\b/ });
54|const InlineKW = createToken({ name: "InlineKW", pattern: /inline\b/ });
55|// `const` may appear inside the ignored struct body.
56|const ConstKW = createToken({
57|  name: "ConstKW",
58|  pattern: /const\b/,
59|  categories: [AnyExceptBrace],
60|});
61|
62|// --- fixed names ------------------------------------------------------------
63|
64|const StdStringView = createToken({
65|  name: "StdStringView",
66|  pattern: /std::string_view\b/,
67|});
68|const StdMap = createToken({ name: "StdMap", pattern: /std::map\b/ });
69|const StdVector = createToken({ name: "StdVector", pattern: /std::vector\b/ });
70|const StdArray = createToken({ name: "StdArray", pattern: /std::array\b/ });
71|// `::` must lex after the `std::…` compounds but before the bare `:`.
72|const ScopeRes = createToken({ name: "ScopeRes", pattern: /::/ });
73|const PropDefsVar = createToken({
74|  name: "PropDefsVar",
75|  pattern: /prop_defs\b/,
76|});
77|const PropSetsVar = createToken({
78|  name: "PropSetsVar",
79|  pattern: /prop_sets\b/,
80|});
81|const ActionsVar = createToken({ name: "ActionsVar", pattern: /actions\b/ });
82|const ActionPropsVar = createToken({
83|  name: "ActionPropsVar",
84|  pattern: /action_props\b/,
85|});
86|const PropIdKW = createToken({ name: "PropIdKW", pattern: /PropId\b/ });
87|const OpenfxNS = createToken({ name: "OpenfxNS", pattern: /openfx\b/ });
88|const TrueKW = createToken({ name: "TrueKW", pattern: /true\b/ });
89|const FalseKW = createToken({ name: "FalseKW", pattern: /false\b/ });
90|
91|// --- punctuation and literals ------------------------------------------------
92|
93|const LBrace = createToken({ name: "LBrace", pattern: /\{/ });
94|const RBrace = createToken({ name: "RBrace", pattern: /\}/ });
95|// These may all appear inside the ignored struct body (constructor signature).
96|const LParen = createToken({
97|  name: "LParen",
98|  pattern: /\(/,
99|  categories: [AnyExceptBrace],
100|});
101|const RParen = createToken({
102|  name: "RParen",
103|  pattern: /\)/,
104|  categories: [AnyExceptBrace],
105|});
106|const LBracket = createToken({ name: "LBracket", pattern: /\[/ });
107|const RBracket = createToken({ name: "RBracket", pattern: /\]/ });
108|const Less = createToken({ name: "Less", pattern: /</ });
109|const Greater = createToken({ name: "Greater", pattern: />/ });
110|const Semicolon = createToken({
111|  name: "Semicolon",
112|  pattern: /;/,
113|  categories: [AnyExceptBrace],
114|});
115|const Comma = createToken({
116|  name: "Comma",
117|  pattern: /,/,
118|  categories: [AnyExceptBrace],
119|});
120|const Colon = createToken({
121|  name: "Colon",
122|  pattern: /:/,
123|  categories: [AnyExceptBrace],
124|});
125|const Star = createToken({
126|  name: "Star",
127|  pattern: /\*/,
128|  categories: [AnyExceptBrace],
129|});
130|const Amp = createToken({
131|  name: "Amp",
132|  pattern: /&/,
133|  categories: [AnyExceptBrace],
134|});
135|const EqEq = createToken({ name: "EqEq", pattern: /==/ });
136|const StringLiteral = createToken({
137|  name: "StringLiteral",
138|  pattern: /"(?:[^"\\\n\r]|\\.)*"/,
139|});
140|const NumberLiteral = createToken({ name: "NumberLiteral", pattern: /\d+/ });
141|const Identifier = createToken({
142|  name: "Identifier",
143|  pattern: /[A-Za-z_][A-Za-z0-9_]*/,
144|  categories: [AnyExceptBrace],
145|});
146|
147|// Longer/compound patterns must precede their prefixes and `Identifier`.
148|const lexerTokens: TokenType[] = [
149|  StaticAssertKW,
150|  EqEq,
151|  StdStringView,
152|  StdMap,
153|  StdVector,
154|  StdArray,
155|  ScopeRes,
156|  NamespaceKW,
157|  StructKW,
158|  StaticKW,
159|  InlineKW,
160|  ConstKW,
161|  PropDefsVar,
162|  PropSetsVar,
163|  ActionsVar,
164|  ActionPropsVar,
165|  PropIdKW,
166|  OpenfxNS,
167|  TrueKW,
168|  FalseKW,
169|  LBrace,
170|  RBrace,
171|  LParen,
172|  RParen,
173|  LBracket,
174|  RBracket,
175|  Less,
176|  Greater,
177|  Semicolon,
178|  Comma,
179|  Colon,
180|  Star,
181|  Amp,
182|  StringLiteral,
183|  NumberLiteral,
184|  Identifier,
185|];
186|const parserTokens: TokenType[] = [
187|  ...lexerTokens,
188|  PragmaOnce,
189|  Include,
190|  AnyExceptBrace,
191|];
192|
193|const ofxLexer = makeHeaderLexer(lexerTokens);
194|
195|// ---------------------------------------------------------------------------
196|// Parser
197|// ---------------------------------------------------------------------------
198|
199|type OpenfxInner = Structure[2]["inner"];
200|
201|class OfxPropsBySetParser extends CstParser {
202|  // --- collected data ---------------------------------------------------------
203|
204|  readonly propSets: Record<string, Record<string, Prop>> = {};
205|  readonly actions: string[] = [];
206|  readonly actionProps: Record<
207|    string,
208|    { inArgs?: Set<string>; outArgs?: Set<string> }
209|  > = {};
210|
211|  // --- structure markers and cross-check state --------------------------------
212|
213|  readonly openfxInner: string[] = [];
214|  /** Name of the prop set whose entries are currently being parsed. */
215|  private currentSet: string | undefined;
216|  /** Last set name, for the strictly-ascending check. */
217|  private lastSetName: string | undefined;
218|  /** Last action_props key, for the strictly-ascending check. */
219|  private lastActionPropKey: string | undefined;
220|  /** Result of the most recent `boolLiteral` subrule. */
221|  private boolValue = false;
222|  /** Index into `actions` past the last static_assert match (order check). */
223|  private assertCursor = 0;
224|  private assertedNames = new Set<string>();
225|
226|  constructor() {
227|    super(parserTokens);
228|    this.performSelfAnalysis();
229|  }
230|
231|  // header: `#pragma once`, includes, then the single `openfx` namespace.
232|  headerFile = this.RULE("headerFile", () => {
233|    this.CONSUME(PragmaOnce);
234|    this.AT_LEAST_ONE(() => this.CONSUME(Include));
235|    this.SUBRULE(this.namespaceOpenfx);
236|    this.CONSUME(EOF);
237|  });
238|
239|  // namespace openfx { struct; prop_sets; actions; action_props; asserts; }
240|  namespaceOpenfx = this.RULE("namespaceOpenfx", () => {
241|    this.CONSUME(NamespaceKW);
242|    this.CONSUME(OpenfxNS);
243|    this.CONSUME(LBrace);
244|    this.SUBRULE(this.structProp);
245|    this.SUBRULE(this.staticPropSets);
246|    this.SUBRULE(this.staticActions);
247|    this.SUBRULE(this.staticActionProps);
248|    this.AT_LEAST_ONE(() => this.SUBRULE(this.staticAssertDeclaration));
249|    this.ACTION(() => this.openfxInner.push("staticAssert[]"));
250|    this.CONSUME(RBrace);
251|  });
252|
253|  // `struct Prop { ... };` -- body is irrelevant to the result.
254|  structProp = this.RULE("structProp", () => {
255|    this.CONSUME(StructKW);
256|    const name = this.CONSUME(Identifier);
257|    this.ACTION(() => {
258|      if (name.image !== "Prop") {
259|        fail(`expected struct name "Prop" but got "${name.image}"`);
260|      }
261|    });
262|    this.SUBRULE(this.braceBlock);
263|    this.CONSUME(Semicolon);
264|    this.ACTION(() => this.openfxInner.push("struct:prop"));
265|  });
266|
267|  // A `{ ... }` block with balanced nested blocks, contents unconstrained
268|  // (but only category-member tokens are allowed inside).
269|  braceBlock = this.RULE("braceBlock", () => {
270|    this.CONSUME(LBrace);
271|    this.MANY(() => {
272|      this.OR([
273|        { ALT: () => this.CONSUME(AnyExceptBrace) },
274|        { ALT: () => this.SUBRULE(this.braceBlock) },
275|      ]);
276|    });
277|    this.CONSUME(RBrace);
278|  });
279|
280|  // static inline const std::map<const char *, std::vector<Prop>> prop_sets
281|  //   { { "Set", { entry, ..., entry } }, ... };
282|  staticPropSets = this.RULE("staticPropSets", () => {
283|    this.CONSUME(StaticKW);
284|    this.CONSUME(InlineKW);
285|    this.CONSUME(ConstKW);
286|    this.CONSUME(StdMap);
287|    this.CONSUME(Less);
288|    this.CONSUME2(ConstKW);
289|    const keyElem = this.CONSUME(Identifier);
290|    this.CONSUME(Star);
291|    this.CONSUME(Comma);
292|    this.CONSUME(StdVector);
293|    this.CONSUME2(Less);
294|    const valueElem = this.CONSUME2(Identifier);
295|    this.CONSUME(Greater);
296|    this.CONSUME2(Greater);
297|    this.CONSUME(PropSetsVar);
298|    this.ACTION(() => {
299|      if (keyElem.image !== "char") {
300|        fail(`unexpected prop_sets key type "${keyElem.image}"`);
301|      }
302|      if (valueElem.image !== "Prop") {
303|        fail(`unexpected prop_sets value type "${valueElem.image}"`);
304|      }
305|    });
306|    this.CONSUME(LBrace);
307|    this.AT_LEAST_ONE(() => this.SUBRULE(this.propSetPair));
308|    this.CONSUME(RBrace);
309|    this.CONSUME(Semicolon);
310|    this.ACTION(() => this.openfxInner.push("static:propSets"));
311|  });
312|
313|  // { "SetName", { entry, ..., entry } }, -- trailing comma on every pair;
314|  // entries inside the vector carry commas between them but not after the
315|  // last one.
316|  propSetPair = this.RULE("propSetPair", () => {
317|    this.CONSUME(LBrace);
318|    const nameTok = this.CONSUME(StringLiteral);
319|    this.CONSUME(Comma);
320|    this.CONSUME2(LBrace);
321|    this.ACTION(() => {
322|      const name = parseCppString(nameTok.image);
323|      if (this.propSets[name] !== undefined) {
324|        fail(`duplicate prop_sets entry "${name}"`);
325|      }
326|      if (this.lastSetName !== undefined && !(this.lastSetName < name)) {
327|        fail(
328|          `prop_sets entry "${name}" does not follow "${this.lastSetName}" ` +
329|            `in ascending order`,
330|        );
331|      }
332|      this.lastSetName = name;
333|      this.currentSet = name;
334|      this.propSets[name] = {};
335|    });
336|    this.SUBRULE(this.propEntry);
337|    this.MANY(() => {
338|      this.CONSUME2(Comma);
339|      this.SUBRULE2(this.propEntry);
340|    });
341|    this.CONSUME(RBrace);
342|    this.CONSUME2(RBrace);
343|    this.CONSUME3(Comma);
344|    this.ACTION(() => {
345|      this.currentSet = undefined;
346|    });
347|  });
348|
349|  // { "Name", prop_defs[PropId::Id], hostWrite, pluginWrite, hostOptional }
350|  propEntry = this.RULE("propEntry", () => {
351|    this.CONSUME(LBrace);
352|    const nameTok = this.CONSUME(StringLiteral);
353|    this.CONSUME(Comma);
354|    this.CONSUME(PropDefsVar);
355|    this.CONSUME(LBracket);
356|    this.CONSUME(PropIdKW);
357|    this.CONSUME(ScopeRes);
358|    const idTok = this.CONSUME(Identifier);
359|    this.CONSUME(RBracket);
360|    this.CONSUME2(Comma);
361|    this.SUBRULE(this.boolLiteral);
362|    const hostWrite = this.boolValue;
363|    this.CONSUME3(Comma);
364|    this.SUBRULE2(this.boolLiteral);
365|    const pluginWrite = this.boolValue;
366|    this.CONSUME4(Comma);
367|    this.SUBRULE3(this.boolLiteral);
368|    const hostOptional = this.boolValue;
369|    this.CONSUME(RBrace);
370|    this.ACTION(() => {
371|      const name = parseCppString(nameTok.image);
372|      const id = idTok.image;
373|      // The prop name is the PropId member, optionally `k`-prefixed.
374|      if (name !== id && name !== `k${id}`) {
375|        fail(`prop entry "${name}" references unexpected PropId "${id}"`);
376|      }
377|      const set = this.currentSet;
378|      if (set === undefined) {
379|        fail(`prop entry "${name}" appears outside a prop set`);
380|      }
381|      // Duplicate names within a set are allowed (the record keeps the last).
382|      this.propSets[set]![name] = {
383|        propDef: id,
384|        hostWrite,
385|        pluginWrite,
386|        hostOptional,
387|      };
388|    });
389|  });
390|
391|  boolLiteral = this.RULE("boolLiteral", () => {
392|    this.boolValue = false;
393|    this.OR([
394|      {
395|        ALT: () => {
396|          this.CONSUME(TrueKW);
397|          this.boolValue = true;
398|        },
399|      },
400|      { ALT: () => this.CONSUME(FalseKW) },
401|    ]);
402|  });
403|
404|  // static inline const std::array<const char *, N> actions { "...", ... };
405|  // every element (including the last) is followed by a comma.
406|  staticActions = this.RULE("staticActions", () => {
407|    this.CONSUME(StaticKW);
408|    this.CONSUME(InlineKW);
409|    this.CONSUME(ConstKW);
410|    this.CONSUME(StdArray);
411|    this.CONSUME(Less);
412|    this.CONSUME2(ConstKW);
413|    const elemType = this.CONSUME(Identifier);
414|    this.CONSUME(Star);
415|    this.CONSUME(Comma);
416|    const countTok = this.CONSUME(NumberLiteral);
417|    this.CONSUME(Greater);
418|    this.CONSUME(ActionsVar);
419|    this.CONSUME(LBrace);
420|    const names: string[] = [];
421|    const first = this.CONSUME(StringLiteral);
422|    this.ACTION(() => names.push(parseCppString(first.image)));
423|    this.MANY(() => {
424|      this.CONSUME2(Comma);
425|      const next = this.CONSUME2(StringLiteral);
426|      this.ACTION(() => names.push(parseCppString(next.image)));
427|    });
428|    this.CONSUME3(Comma);
429|    this.CONSUME(RBrace);
430|    this.CONSUME(Semicolon);
431|    this.ACTION(() => {
432|      if (elemType.image !== "char") {
433|        fail(`unexpected actions element type "${elemType.image}"`);
434|      }
435|      const declared = toInt(countTok.image, "actions element count");
436|      if (declared !== names.length) {
437|        fail(
438|          `actions declares ${declared} element(s) but lists ${names.length}`,
439|        );
440|      }
441|      for (let i = 1; i < names.length; i++) {
442|        if (!(names[i - 1]! < names[i]!)) {
443|          fail(
444|            `actions name "${names[i]}" does not follow "${names[i - 1]}" ` +
445|              `in ascending order`,
446|          );
447|        }
448|      }
449|      this.actions.push(...names);
450|      this.openfxInner.push("static:actions");
451|    });
452|  });
453|
454|  // static inline const
455|  //   std::map<std::array<std::string_view, 2>, std::vector<const char *>>
456|  //   action_props { { { "Action", kind }, { "Value", ... } }, ... };
457|  staticActionProps = this.RULE("staticActionProps", () => {
458|    this.CONSUME(StaticKW);
459|    this.CONSUME(InlineKW);
460|    this.CONSUME(ConstKW);
461|    this.CONSUME(StdMap);
462|    this.CONSUME(Less);
463|    this.CONSUME(StdArray);
464|    this.CONSUME2(Less);
465|    this.CONSUME(StdStringView);
466|    this.CONSUME(Comma);
467|    const keyArity = this.CONSUME(NumberLiteral);
468|    this.CONSUME(Greater);
469|    this.CONSUME2(Comma);
470|    this.CONSUME(StdVector);
471|    this.CONSUME3(Less);
472|    this.CONSUME2(ConstKW);
473|    const elemType = this.CONSUME(Identifier);
474|    this.CONSUME(Star);
475|    this.CONSUME2(Greater);
476|    this.CONSUME3(Greater);
477|    this.CONSUME(ActionPropsVar);
478|    this.ACTION(() => {
479|      // The key is an (action, kind) pair; the pair shape requires arity 2.
480|      if (toInt(keyArity.image, "action_props key arity") !== 2) {
481|        fail(`unexpected action_props key arity "${keyArity.image}"`);
482|      }
483|      if (elemType.image !== "char") {
484|        fail(`unexpected action_props element type "${elemType.image}"`);
485|      }
486|    });
487|    this.CONSUME(LBrace);
488|    this.AT_LEAST_ONE(() => this.SUBRULE(this.actionPropsEntry));
489|    this.CONSUME(RBrace);
490|    this.CONSUME(Semicolon);
491|    this.ACTION(() => this.openfxInner.push("static:actionProps"));
492|  });
493|
494|  // { { "Action", inArgs|outArgs }, { "Value", ..., "Value" } },
495|  // (trailing comma on every entry).
496|  actionPropsEntry = this.RULE("actionPropsEntry", () => {
497|    this.CONSUME(LBrace);
498|    this.CONSUME2(LBrace);
499|    const actionTok = this.CONSUME(StringLiteral);
500|    this.CONSUME(Comma);
