502|    this.ACTION(() => {
503|      const kind = parseCppString(kindTok.image);
504|      if (kind !== "inArgs" && kind !== "outArgs") {
505|        fail(`unexpected action_props key kind "${kind}"`);
506|      }
507|    });
508|    this.CONSUME(RBrace);
509|    this.CONSUME2(Comma);
510|    this.CONSUME3(LBrace);
511|    const values: string[] = [];
512|    const first = this.CONSUME3(StringLiteral);
513|    this.ACTION(() => values.push(parseCppString(first.image)));
514|    this.MANY(() => {
515|      this.CONSUME3(Comma);
516|      const next = this.CONSUME4(StringLiteral);
517|      this.ACTION(() => values.push(parseCppString(next.image)));
518|    });
519|    this.CONSUME2(RBrace);
520|    this.CONSUME3(RBrace);
521|    this.CONSUME4(Comma);
522|    this.ACTION(() => {
523|      const action = parseCppString(actionTok.image);
524|      const kindName = parseCppString(kindTok.image) as "inArgs" | "outArgs";
525|      const key = JSON.stringify([action, kindName]);
526|      if (
527|        this.lastActionPropKey !== undefined && !(this.lastActionPropKey < key)
528|      ) {
529|        fail(
530|          `action_props entry ${key} does not follow ${this.lastActionPropKey}` +
531|            ` in ascending order`,
532|        );
533|      }
534|      this.lastActionPropKey = key;
535|      if (!this.actions.includes(action)) {
536|        fail(`action_props references "${action}", which is not in actions`);
537|      }
538|      for (let i = 1; i < values.length; i++) {
539|        if (values[i - 1]! > values[i]!) {
540|          fail(
541|            `action_props ${key}: value "${values[i]}" does not follow ` +
542|              `"${values[i - 1]}" in non-decreasing order`,
543|          );
544|        }
545|      }
546|      const entry = this.actionProps[action] ??= {};
547|      if (entry[kindName] !== undefined) {
548|        fail(`duplicate action_props entry ${key}`);
549|      }
550|      entry[kindName] = new Set(values);
551|    });
552|  });
553|
554|  // static_assert(std::string_view("Name") == std::string_view(kName));
555|  staticAssertDeclaration = this.RULE("staticAssertDeclaration", () => {
556|    this.CONSUME(StaticAssertKW);
557|    this.CONSUME(LParen);
558|    this.CONSUME(StdStringView);
559|    this.CONSUME2(LParen);
560|    const nameTok = this.CONSUME(StringLiteral);
561|    this.CONSUME(RParen);
562|    this.CONSUME(EqEq);
563|    this.CONSUME2(StdStringView);
564|    this.CONSUME3(LParen);
565|    const identTok = this.CONSUME(Identifier);
566|    this.CONSUME2(RParen);
567|    this.CONSUME3(RParen);
568|    this.CONSUME(Semicolon);
569|    this.ACTION(() => {
570|      const name = parseCppString(nameTok.image);
571|      if (identTok.image !== `k${name}`) {
572|        fail(`static_assert compares "${name}" with "${identTok.image}"`);
573|      }
574|      if (this.assertedNames.has(name)) {
575|        fail(`duplicate static_assert for "${name}"`);
576|      }
577|      this.assertedNames.add(name);
578|      // Asserts must appear in the same relative order as `actions`.
579|      const idx = this.actions.indexOf(name, this.assertCursor);
580|      if (idx === -1) {
581|        fail(`static_assert references "${name}", which is not in actions`);
582|      }
583|      this.assertCursor = idx + 1;
