607|  return {
608|    structure: [
609|      "pragmaOnce",
610|      "include[]",
611|      {
612|        type: "namespace:openfx",
613|        // The grammar pushes exactly the elements the Structure schema
614|        // prescribes, in order; the cast only fixes up the tuple type.
615|        inner: [...parser.openfxInner] as unknown as OpenfxInner,
616|      },
