{"content": "1|// Parser for `ofxPropsMetadata.h`, implemented per ./INSTRUCTIONS.md.
2|//
3|// The grammar mirrors the `Structure` schema in ../types.ts one-to-one: every
4|// element of the expected structure corresponds to exactly one parser rule,
5|// and the rules appear in exactly the order the structure tuple prescribes.
6|// Anything the header adds, removes, or reorders therefore fails the parse.
7|// Regions whose contents do not contribute to the result (struct bodies,
8|// template parameter lists, static_assert expressions) are consumed through
9|// token-category "soup" rules that are still bracket-delimited and strict
10|// about the surrounding shape.
11|
12|import { createToken, CstParser, EOF, Lexer } from "chevrotain";
13|import type { TokenType } from "chevrotain";
14|import {
15|  fail,
16|  Include,
17|  lexingError,
18|  makeHeaderLexer,
19|  parseCppString,
20|  parsingError,
21|  PragmaOnce,
22|  toInt,
23|} from "../../common-by-llms/mod.ts";
24|import type { LexIssue, ParseIssue } from "../../common-by-llms/mod.ts";
25|import { PropTypeSimple as PropTypeSimpleSchema } from "../types.ts";
26|import type {
27|  FinalResult,
28|  PropType,
29|  PropTypeSimple,
30|  Result,
31|  Structure,
32|} from "../types.ts";
33|
34|/** The canonical PropType set, taken from ../types.ts (single source of truth). */
35|const PROP_TYPES = new Set<string>([...PropTypeSimpleSchema.options, "Enum"]);
36|
37|// ---------------------------------------------------------------------------
38|// Tokens
39|// ---------------------------------------------------------------------------
40|
41|// --- skipped by the lexer ---------------------------------------------------
42|// Trivia tokens live in ../../common-by-llms (shared with the other header
43|// parsers) and are re-exported here only as needed by the token lists below.
44|
45|// --- token categories -------------------------------------------------------
46|// Categories let the grammar consume "any token except X" inside regions whose
47|// exact contents do not contribute to the result. Membership is deliberately
48|// narrow: tokens that would indicate a structural surprise (e.g. a `namespace`
49|// keyword inside a struct body) are not members of any category, so their
50|// appearance there is a parse error.
51|
52|const AnyExceptBrace = createToken({
53|  name: "AnyExceptBrace",
54|  pattern: Lexer.NA,
55|});
56|const AnyExceptParenOrSemicolon = createToken({
57|  name: "AnyExceptParenOrSemicolon",
58|  pattern: Lexer.NA,
59|});
60|const AnyExceptAngleOrComma = createToken({
61|  name: "AnyExceptAngleOrComma",
62|  pattern: Lexer.NA,
63|});
64|
65|const soupEverywhere = [
66|  AnyExceptBrace,
67|  AnyExceptParenOrSemicolon,
68|  AnyExceptAngleOrComma,
69|];
70|const soupBraceAndParen = [AnyExceptBrace, AnyExceptParenOrSemicolon];
71|const soupBraceAndTemplate = [AnyExceptBrace, AnyExceptAngleOrComma];
72|
73|// --- preprocessor -----------------------------------------------------------
74|
75|// `#pragma once`, includes and trivia come from ../../common-by-llms. This
76|// dialect additionally allows a whole `#define ...` directive including
77|// backslash-newline continuations (a newline may only appear escaped).
78|const DefineDirective = createToken({
79|  name: "DefineDirective",
80|  pattern: /#define(?:[^\\\n\r]|\\[\s\S])*/,
81|});
82|
83|// --- keywords ---------------------------------------------------------------
84|// Keywords that may legitimately appear inside skipped regions carry the
85|// corresponding soup categories; the rest do not.
86|
87|const NamespaceKW = createToken({
88|  name: "NamespaceKW",
89|  pattern: /namespace\b/,
90|});
91|const EnumKW = createToken({ name: "EnumKW", pattern: /enum\b/ });
92|const ClassKW = createToken({ name: "ClassKW", pattern: /class\b/ });
93|const StructKW = createToken({ name: "StructKW", pattern: /struct\b/ });
94|const UsingKW = createToken({ name: "UsingKW", pattern: /using\b/ });
95|const StaticAssertKW = createToken({
96|  name: "StaticAssertKW",
97|  pattern: /static_assert\b/,
98|});
99|const StaticKW = createToken({
100|  name: "StaticKW",
101|  pattern: /static\b/,
102|  categories: soupEverywhere,
103|});
104|const InlineKW = createToken({
105|  name: "InlineKW",
106|  pattern: /inline\b/,
107|  categories: soupEverywhere,
108|});
109|const ConstexprKW = createToken({
110|  name: "ConstexprKW",
111|  pattern: /constexpr\b/,
112|  categories: soupEverywhere,
113|});
114|const ConstKW = createToken({
115|  name: "ConstKW",
116|  pattern: /const\b/,
117|  categories: soupEverywhere,
118|});
119|const TemplateKW = createToken({
120|  name: "TemplateKW",
121|  pattern: /template\b/,
122|  categories: soupEverywhere,
123|});
124|const TypenameKW = createToken({
125|  name: "TypenameKW",
126|  pattern: /typename\b/,
127|  categories: soupEverywhere,
128|});
129|
130|// --- fixed multi-word symbols ------------------------------------------------
131|// `PropType` may appear inside skipped regions (e.g. struct fields), so it
132|// carries soup categories too; the namespace/variable names do not.
133|
134|const OpenfxSpan = createToken({
135|  name: "OpenfxSpan",
136|  pattern: /openfx::span\b/,
137|  categories: soupEverywhere,
138|});
139|const StdArray = createToken({
140|  name: "StdArray",
141|  pattern: /std::array\b/,
142|  categories: soupEverywhere,
143|});
144|const PropTypeKW = createToken({
145|  name: "PropTypeKW",
146|  pattern: /PropType\b/,
147|  categories: soupEverywhere,
148|});
149|const OpenfxNS = createToken({ name: "OpenfxNS", pattern: /openfx\b/ });
150|const PropEnumValuesNS = createToken({
151|  name: "PropEnumValuesNS",
152|  pattern: /prop_enum_values\b/,
153|});
154|const PropTypeArraysNS = createToken({
155|  name: "PropTypeArraysNS",
156|  pattern: /prop_type_arrays\b/,
157|});
158|const PropertiesNS = createToken({
159|  name: "PropertiesNS",
160|  pattern: /properties\b/,
161|});
162|const AssertionsNS = createToken({
163|  name: "AssertionsNS",
164|  pattern: /assertions\b/,
165|});
166|const PropDefsVar = createToken({
167|  name: "PropDefsVar",
168|  pattern: /prop_defs\b/,
169|});
170|const DefinePropTraitsKW = createToken({
171|  name: "DefinePropTraitsKW",
172|  pattern: /DEFINE_PROP_TRAITS\b/,
173|});
174|
175|// --- punctuation and literals ------------------------------------------------
176|
177|const LBrace = createToken({ name: "LBrace", pattern: /\{/ });
178|const RBrace = createToken({ name: "RBrace", pattern: /\}/ });
179|const LParen = createToken({
180|  name: "LParen",
181|  pattern: /\(/,
182|  categories: soupBraceAndTemplate,
183|});
184|const RParen = createToken({
185|  name: "RParen",
186|  pattern: /\)/,
187|  categories: soupBraceAndTemplate,
188|});
189|const LBracket = createToken({
190|  name: "LBracket",
191|  pattern: /\[/,
192|  categories: soupEverywhere,
193|});
194|const RBracket = createToken({
195|  name: "RBracket",
196|  pattern: /\]/,
197|  categories: soupEverywhere,
198|});
199|const Less = createToken({
200|  name: "Less",
201|  pattern: /</,
202|  categories: soupBraceAndParen,
203|});
204|const Greater = createToken({
205|  name: "Greater",
206|  pattern: />/,
207|  categories: soupBraceAndParen,
208|});
209|const Semicolon = createToken({
210|  name: "Semicolon",
211|  pattern: /;/,
212|  categories: soupBraceAndTemplate,
213|});
214|const Comma = createToken({
215|  name: "Comma",
216|  pattern: /,/,
217|  categories: soupBraceAndParen,
218|});
219|const Equals = createToken({
220|  name: "Equals",
221|  pattern: /=/,
222|  categories: soupEverywhere,
223|});
224|const EqEq = createToken({
225|  name: "EqEq",
226|  pattern: /==/,
227|  categories: soupEverywhere,
228|});
229|const Star = createToken({
230|  name: "Star",
231|  pattern: /\*/,
232|  categories: soupEverywhere,
233|});
234|const Amp = createToken({
235|  name: "Amp",
236|  pattern: /&/,
237|  categories: soupEverywhere,
238|});
239|const Dot = createToken({
240|  name: "Dot",
241|  pattern: /\./,
242|  categories: soupEverywhere,
243|});
244|const ScopeRes = createToken({
245|  name: "ScopeRes",
246|  pattern: /::/,
247|  categories: soupEverywhere,
248|});
249|const StringLiteral = createToken({
250|  name: "StringLiteral",
251|  pattern: /"(?:[^"\\\n\r]|\\.)*"/,
252|  categories: soupEverywhere,
253|});
254|const NumberLiteral = createToken({
255|  name: "NumberLiteral",
256|  pattern: /\d+/,
257|  categories: soupEverywhere,
258|});
259|const Identifier = createToken({
260|  name: "Identifier",
261|  pattern: /[A-Za-z_][A-Za-z0-9_]*/,
262|  categories: soupEverywhere,
263|});
264|
265|const dialectTokens: TokenType[] = [
266|  // `#define` is specific to this dialect (the DEFINE_PROP_TRAITS macro).
267|  DefineDirective,
268|  // Longer keywords before shorter prefixes and before Identifier.
269|  StaticAssertKW,
270|  EqEq,
271|  ScopeRes,
272|  ConstexprKW,
273|  NamespaceKW,
274|  EnumKW,
275|  ClassKW,
276|  StructKW,
277|  StaticKW,
278|  InlineKW,
279|  ConstKW,
280|  UsingKW,
281|  TemplateKW,
282|  TypenameKW,
283|  OpenfxSpan,
284|  StdArray,
285|  PropTypeKW,
286|  OpenfxNS,
287|  PropEnumValuesNS,
288|  PropTypeArraysNS,
289|  PropertiesNS,
290|  AssertionsNS,
291|  PropDefsVar,
292|  DefinePropTraitsKW,
293|  LBrace,
294|  RBrace,
295|  LParen,
296|  RParen,
297|  LBracket,
298|  RBracket,
299|  Less,
300|  Greater,
301|  Semicolon,
302|  Comma,
303|  Equals,
304|  Star,
305|  Amp,
306|  Dot,
307|  StringLiteral,
308|  NumberLiteral,
309|  Identifier,
310|];
311|const parserTokens = [
312|  ...dialectTokens,
313|  PragmaOnce,
314|  Include,
315|  AnyExceptBrace,
316|  AnyExceptParenOrSemicolon,
317|  AnyExceptAngleOrComma,
318|];
319|
320|const ofxLexer = makeHeaderLexer(dialectTokens);
321|
322|// ---------------------------------------------------------------------------
323|// Parser
324|// ---------------------------------------------------------------------------
325|
326|type OpenfxInner = Structure[2]["inner"];
327|type OpenfxInnerElement = OpenfxInner[number];
328|type PropertiesInner = Extract<
329|  OpenfxInnerElement,
330|  { type: "namespace:properties" }
331|>["inner"];
332|type AssertionsInner = Extract<
333|  OpenfxInnerElement,
334|  { type: "namespace:assertions" }
335|>["inner"];
336|
337|class OfxPropsMetadataParser extends CstParser {
338|  // --- collected data ---------------------------------------------------------
339|
340|  readonly propEnumValues: Record<string, Set<string>> = {};
341|  readonly propTypeArrays: Record<string, Set<PropType>> = {};
342|  readonly propDefsArray: Record<string, { dimension: number }[]> = {};
343|  /** Ids of DEFINE_PROP_TRAITS calls, in header order. */
344|  readonly propTraitsCallIds: string[] = [];
345|  /** Members of the `enum class PropId` (excluding the trailing NProps). */
346|  readonly propIdNames: string[] = [];
347|
348|  // --- structure markers ------------------------------------------------------
349|  // Pushed by each section rule, in exactly the order the grammar enforces.
350|
351|  readonly openfxInner: OpenfxInnerElement[] = [];
352|  readonly propertiesInner: PropertiesInner[number][] = [];
353|  readonly assertionsInner: AssertionsInner[number][] = [];
354|
355|  constructor() {
356|    super(parserTokens);
357|    this.performSelfAnalysis();
358|  }
359|
360|  // header: `#pragma once`, includes, then the single `openfx` namespace.
361|  headerFile = this.RULE("headerFile", () => {
362|    this.CONSUME(PragmaOnce);
363|    this.AT_LEAST_ONE(() => this.CONSUME(Include));
364|    this.SUBRULE(this.namespaceOpenfx);
365|    this.CONSUME(EOF);
366|  });
367|
368|  namespaceOpenfx = this.RULE("namespaceOpenfx", () => {
369|    this.CONSUME(NamespaceKW);
370|    this.CONSUME(OpenfxNS);
371|    this.CONSUME(LBrace);
372|    this.SUBRULE(this.enumPropType);
373|    this.SUBRULE(this.enumPropId);
374|    this.SUBRULE(this.namespacePropEnumValues);
375|    this.SUBRULE(this.namespacePropTypeArrays);
376|    this.SUBRULE(this.structPropDef);
377|    this.SUBRULE(this.templateStructPropDefsArray);
378|    this.SUBRULE(this.staticPropDefs);
379|    this.SUBRULE(this.namespaceProperties);
380|    this.SUBRULE(this.namespaceAssertions);
381|    this.CONSUME(RBrace);
382|  });
383|
384|  // `enum class PropType { Int, Double, Enum, Bool, String, Pointer };`
385|  enumPropType = this.RULE("enumPropType", () => {
386|    this.CONSUME(EnumKW);
387|    this.CONSUME(ClassKW);
388|    this.CONSUME(PropTypeKW);
389|    this.CONSUME(LBrace);
390|    const enumerators: string[] = [];
391|    const first = this.CONSUME(Identifier);
392|    this.ACTION(() => enumerators.push(first.image));
393|    this.MANY(() => {
394|      this.CONSUME(Comma);
395|      const next = this.CONSUME2(Identifier);
396|      this.ACTION(() => enumerators.push(next.image));
397|    });
398|    this.CONSUME(RBrace);
399|    this.CONSUME(Semicolon);
400|    this.ACTION(() => {
401|      // The grammar rule only sees identifiers; validate that the enumerator
402|      // set is exactly the canonical PropType set (order-insensitive).
403|      const actual = new Set(enumerators);
404|      if (
405|        actual.size !== PROP_TYPES.size ||
406|        enumerators.some((e) => !PROP_TYPES.has(e))
407|      ) {
408|        fail(
409|          `enum PropType enumerators ${JSON.stringify(enumerators)} do not ` +
410|            `match the canonical PropType set ${
411|              JSON.stringify([...PROP_TYPES])
412|            }`,
413|        );
414|      }
415|      this.openfxInner.push("enum:propType");
416|    });
417|  });
418|
419|  // `enum class PropId { ... };` -- only the member names matter (they are
420|  // the ids referenced by DEFINE_PROP_TRAITS).
421|  enumPropId = this.RULE("enumPropId", () => {
422|    this.CONSUME(EnumKW);
423|    this.CONSUME(ClassKW);
424|    const name = this.CONSUME(Identifier);
425|    this.ACTION(() => {
426|      if (name.image !== "PropId") {
427|        fail(`expected enum name "PropId" but got "${name.image}"`);
428|      }
429|    });
430|    this.CONSUME(LBrace);
431|    const first = this.CONSUME2(Identifier);
432|    this.ACTION(() => this.propIdNames.push(first.image));
433|    this.MANY(() => {
434|      this.CONSUME(Comma);
435|      const next = this.CONSUME3(Identifier);
436|      this.ACTION(() => this.propIdNames.push(next.image));
437|    });
438|    this.CONSUME(RBrace);
439|    this.CONSUME(Semicolon);
440|    this.ACTION(() => {
441|      const sentinel = this.propIdNames.pop();
442|      if (sentinel !== "NProps") {
443|        fail(
444|          `expected the PropId enum to end with the "NProps" sentinel but got "${
445|            sentinel ?? "<none>"
446|          }"`,
447|        );
448|      }
449|      if (new Set(this.propIdNames).size !== this.propIdNames.length) {
450|        fail("duplicate members in the PropId enum");
451|      }
452|    });
453|    this.ACTION(() => this.openfxInner.push("enum:propId"));
454|  });
455|
456|  // namespace prop_enum_values { constexpr std::array X = {...}; ... }
457|  namespacePropEnumValues = this.RULE("namespacePropEnumValues", () => {
458|    this.CONSUME(NamespaceKW);
