881|const HEADER_NAME = "ofxPropsMetadata.h";
882|
883|export function parse(headerCode: string): Result {
884|  const lexingResult = ofxLexer.tokenize(headerCode);
885|  if (lexingResult.errors.length > 0) {
886|    lexingError(HEADER_NAME, headerCode, lexingResult.errors as LexIssue[]);
887|  }
888|
889|  const parser = new OfxPropsMetadataParser();
890|  parser.input = lexingResult.tokens;
891|  parser.headerFile();
892|  if (parser.errors.length > 0) {
893|    parsingError(HEADER_NAME, headerCode, parser.errors as ParseIssue[]);
894|  }
895|
896|  return {
897|    structure: [
898|      "pragmaOnce",
899|      "include[]",
900|      {
901|        type: "namespace:openfx",
902|        // The grammar pushes exactly the elements the Structure schema
903|        // prescribes, in order; the cast only fixes up the tuple type.
904|        inner: parser.openfxInner as unknown as OpenfxInner,
905|      },
906|    ],
907|    propertyInfos: {
908|      propEnumValues: parser.propEnumValues,
909|      propTypeArrays: parser.propTypeArrays,
910|      propDefsArray: parser.propDefsArray,
911|    },
912|  };
913|}
914|
915|export function makeFinalResult(result: Result): FinalResult {
916|  const { propEnumValues, propTypeArrays, propDefsArray } =
917|    result.propertyInfos;
918|  const propertyInfos: FinalResult["propertyInfos"] = {};
919|
920|  // A property whose value can have an enum type must not have any other type.
921|  for (const [name, types] of Object.entries(propTypeArrays)) {
922|    if (types.has("Enum") && types.size > 1) {
923|      fail(
924|        `prop_type_arrays entry "${name}" mixes "Enum" with other types ` +
925|          `(${JSON.stringify([...types])}); enum-typed properties must have ` +
926|          `"Enum" as their only type`,
927|      );
928|    }
929|  }
930|
931|  for (const [name, entries] of Object.entries(propDefsArray)) {
932|    const entry = entries[0];
933|    if (entry === undefined) {
934|      fail(`no prop_defs entry recorded for "${name}"`);
935|    }
936|    const types = propTypeArrays[`${name}_types`];
937|    if (types === undefined) {
938|      fail(`missing prop_type_arrays entry for "${name}"`);
939|    }
940|    if (types.size === 0) {
941|      fail(`empty prop_type_arrays entry for "${name}"`);
942|    }
943|    // Set iteration order is insertion order, i.e. header order.
944|    const isEnum = types.has("Enum");
945|    const simpleTypes = new Set<PropTypeSimple>(
946|      [...types].filter((t): t is PropTypeSimple => t !== "Enum"),
947|    );
948|    propertyInfos[name] = {
949|      type: isEnum
950|        // The Enum value is the key of this property's entry in
951|        // `propEnumValues`, which the final result also carries.
952|        ? { Enum: name }
953|        // A set with a single type collapses to that type; a set with several
954|        // types is a multitype property (e.g. OfxParamPropDefault).
955|        : simpleTypes.size === 1 ? [...simpleTypes][0] : simpleTypes,
956|      dimension: entry.dimension,
957|    };
958|  }
959|
960|  return { propEnumValues, propertyInfos };
