{"content": "1|// Additional tests for the behaviors introduced by INSTRUCTIONS.md
2|// "Instructions for update 1": `prop_type_arrays` entries with multiple
3|// types, and the rule that an enum-typed property must not have any other
4|// type. This module is imported by ../mod.test.ts and runs under `deno test`
5|// with the same `--crate-path` argument.
6|
7|import path from "node:path";
8|
9|import { assert, assertEquals, assertThrows } from "@std/assert";
10|import { parseArgs } from "@std/cli/parse-args";
11|
12|import { makeFinalResult, parse } from "./mod.ts";
13|import type { PropType, Result } from "../types.ts";
14|
15|const args = parseArgs(Deno.args, {
16|  string: ["crate-path"],
17|});
18|
19|if (!args["crate-path"]) throw new Error("Missing `--crate-path`");
20|
21|const headerPath = path.join(
22|  args["crate-path"],
23|  "vendor",
24|  "openfx",
25|  "openfx-cpp",
26|  "include",
27|  "openfx",
28|  "ofxPropsMetadata.h",
29|);
30|
31|const headerCode = await Deno.readTextFile(headerPath);
32|const result = parse(headerCode);
33|const finalResult = makeFinalResult(result);
34|
35|/** The first `*_types` array entry satisfying `pred`, as [name, types]. */
36|function findTypeArray(
37|  res: Result,
38|  pred: (types: ReadonlySet<string>) => boolean,
39|): [string, Set<PropType>] {
40|  const entry = Object.entries(res.propertyInfos.propTypeArrays).find(([, t]) =>
41|    pred(t)
42|  );
43|  assert(entry !== undefined, "no matching prop_type_arrays entry in header");
44|  return entry;
45|}
46|
47|Deno.test("update 1: multitype properties keep the full type set", () => {
48|  // The acceptance example from INSTRUCTIONS.md.
49|  const type = finalResult.propertyInfos["OfxParamPropDefault"].type;
50|  assert(type instanceof Set, "expected OfxParamPropDefault to be multitype");
51|  assertEquals(type, new Set(["Int", "Double", "String", "Pointer"]));
52|});
53|
54|Deno.test("update 1: multitype sets mirror the raw type arrays", () => {
55|  for (
56|    const [typesName, types] of Object.entries(
57|      result.propertyInfos.propTypeArrays,
58|    )
59|  ) {
60|    if (types.has("Enum") || types.size === 1) continue;
61|    const name = typesName.replace(/_types$/, "");
62|    const info = finalResult.propertyInfos[name];
63|    assert(info !== undefined, `no final entry for multitype "${name}"`);
64|    assert(info.type instanceof Set, `expected "${name}" to stay a Set`);
65|    assertEquals(info.type, types);
66|  }
67|});
68|
69|Deno.test("single-type properties collapse to the bare type", () => {
70|  for (
71|    const [typesName, types] of Object.entries(
72|      result.propertyInfos.propTypeArrays,
73|    )
74|  ) {
75|    const [only] = types;
76|    if (types.size !== 1 || only === "Enum") continue;
77|    const name = typesName.replace(/_types$/, "");
78|    const info = finalResult.propertyInfos[name];
79|    assert(info !== undefined, `no final entry for "${name}"`);
80|    assertEquals(info.type, only);
81|  }
82|});
83|
84|Deno.test("enum-typed properties map to { Enum: name } with values", () => {
85|  for (
86|    const [typesName, types] of Object.entries(
87|      result.propertyInfos.propTypeArrays,
88|    )
89|  ) {
90|    if (!types.has("Enum")) continue;
91|    const name = typesName.replace(/_types$/, "");
92|    const info = finalResult.propertyInfos[name];
93|    assert(info !== undefined, `no final entry for enum-typed "${name}"`);
94|    assertEquals(info.type, { Enum: name });
95|    assert(
96|      name in finalResult.propEnumValues,
97|      `enum-typed "${name}" has no prop_enum_values entry`,
98|    );
99|  }
100|});
101|
102|Deno.test("update 1: mixing Enum with another type throws", () => {
103|  // "Int" added to an enum-only array.
104|  const enumAdded = structuredClone(result);
105|  findTypeArray(enumAdded, (t) => t.has("Enum"))[1].add("Int");
106|  assertThrows(() => makeFinalResult(enumAdded), Error, `mixes "Enum"`);
107|
108|  // "Enum" added to a multitype (non-enum) array.
109|  const multiAdded = structuredClone(result);
110|  findTypeArray(multiAdded, (t) => t.size > 1 && !t.has("Enum"))[1].add(
111|    "Enum",
112|  );
113|  assertThrows(() => makeFinalResult(multiAdded), Error, `mixes "Enum"`);
114|
115|  // The check fires even for arrays not referenced by any prop_defs entry.
116|  const unreferenced = structuredClone(result);
117|  const [typesName, types] = findTypeArray(unreferenced, (t) => t.has("Enum"));
118|  delete unreferenced.propertyInfos.propDefsArray[
119|    typesName.replace(/_types$/, "")
120|  ];
121|  types.add("Int");
122|  assertThrows(() => makeFinalResult(unreferenced), Error, `mixes "Enum"`);
123|});
124|
125|Deno.test("update 1: unknown PropType enumerator is rejected", () => {
126|  // Rewrite the first single-entry type array to use a bogus enumerator.
127|  const mutated = headerCode.replace(
128|    /\{PropType::[A-Za-z]+\}/,
129|    "{PropType::Bogus}",
130|  );
131|  assert(mutated !== headerCode, "no single-entry type array found to mutate");
132|  assertThrows(() => parse(mutated), Error, "unknown type");
133|});
