{"content": "1|// Scaffolding shared between the ofx header parsers
2|// (`parser-ofxPropsMetadata` and `parser-ofxPropsBySet`), moved here per the
3|// instructions in each parser's `impl-by-llms/INSTRUCTIONS.md`.
4|//
5|// Everything here is dialect-agnostic: trivia tokens that carry no token
6|// categories, preprocessor tokens common to the headers, and small helpers
7|// used by both implementations. Anything that varies between header dialects
8|// (soup categories, keywords, error messages) stays in the parsers.
9|
10|import { createToken, Lexer } from "chevrotain";
11|import type { TokenType } from "chevrotain";
12|
13|// ---------------------------------------------------------------------------
14|// Tokens
15|// ---------------------------------------------------------------------------
16|
17|// --- skipped by the lexer ---------------------------------------------------
18|
19|export const WhiteSpace = createToken({
20|  name: "WhiteSpace",
21|  pattern: /\s+/,
22|  group: Lexer.SKIPPED,
23|});
24|export const LineComment = createToken({
25|  name: "LineComment",
26|  pattern: /\/\/[^\n\r]*/,
27|  group: Lexer.SKIPPED,
28|});
29|export const BlockComment = createToken({
30|  name: "BlockComment",
31|  pattern: /\/\*[\s\S]*?\*\//,
32|  group: Lexer.SKIPPED,
33|});
34|
35|// --- preprocessor -----------------------------------------------------------
36|
37|// `#pragma once` (and nothing else -- any other pragma fails to lex).
38|export const PragmaOnce = createToken({
39|  name: "PragmaOnce",
40|  pattern: /#pragma[ \t]+once\b/,
41|});
42|export const Include = createToken({ name: "Include", pattern: Lexer.NA });
43|export const IncludeAngle = createToken({
44|  name: "IncludeAngle",
45|  pattern: /#include[ \t]*<[^>\n\r]*>/,
46|  categories: [Include],
47|});
48|export const IncludeQuoted = createToken({
49|  name: "IncludeQuoted",
50|  pattern: /#include[ \t]*"[^"\n\r]*"/,
51|  categories: [Include],
52|});
53|
54|/**
55| * Trivia and preprocessor tokens shared by every header dialect, in lexer
56| * order (they must precede any dialect token that could match their text).
57| */
58|export const headerBaseTokens: TokenType[] = [
59|  WhiteSpace,
60|  LineComment,
61|  BlockComment,
62|  PragmaOnce,
63|  IncludeAngle,
64|  IncludeQuoted,
65|];
66|
67|/**
68| * A lexer for one header dialect: the shared trivia/preprocessor tokens
69| * first, then the dialect's own tokens.
70| */
71|export function makeHeaderLexer(dialectTokens: TokenType[]): Lexer {
72|  return new Lexer([...headerBaseTokens, ...dialectTokens], {
73|    positionTracking: "onlyOffset",
74|  });
75|}
76|
77|// ---------------------------------------------------------------------------
78|// Helpers
79|// ---------------------------------------------------------------------------
80|
81|/** Throws the given message; used to fail from inside parser ACTIONs. */
82|export function fail(message: string): never {
83|  throw new Error(message);
84|}
85|
86|/** Maps a token offset in the source to a 1-based line number. */
87|export function lineOf(source: string, offset: number): number {
88|  let line = 1;
89|  for (let i = 0; i < offset && i < source.length; i++) {
90|    if (source.charCodeAt(i) === 10) line++;
91|  }
92|  return line;
93|}
94|
95|/**
96| * Parses the simple string literals used by the headers. They contain plain
97| * quoted identifiers only; anything fancier is a structural change and is
98| * rejected.
99| */
100|export function parseCppString(image: string): string {
101|  if (
102|    image.length < 2 || image[0] !== '"' || image[image.length - 1] !== '"' ||
103|    image.slice(1, -1).includes('"') || image.slice(1, -1).includes("\\")
