export function makeFinalResult(result: Result): FinalResult {
  // Strip the `k` prefix from the assertion values: the map's keys are the
  // constant values as they appear in C++ string literals, and its values are
  // the constant names without the `k` prefix (per ../types.ts).
  const keyConstantToCanonicalNameMap: Record<string, string> = {};
  for (const [value, constant] of Object.entries(result.infos.assertions)) {
    if (!constant.startsWith("k")) {
      fail(`key constant "${constant}" lacks the "k" prefix`);
    }
    keyConstantToCanonicalNameMap[value] = constant.slice(1);
  }
  return { infos: result.infos, keyConstantToCanonicalNameMap };
}
```

