{"content":"// Ad-hoc verification of INSTRUCTIONS.md "update 2" map orientation:
//   Result.assertions        : constant value -> key constant (with `k`)
//   FinalResult.keyConstantToCanonicalNameMap : constant value -> name sans `k`
// Run with:
//   deno run --allow-read --config <scripts>/deno.json hermes-verify-update2.ts

import {
  makeFinalResult,
  parse,
} from "/Volumes/Tertiary/CodingProjects/Maintaining/kreantio/openfx-rs/crates/openfx/scripts/src/parsers/parser-ofxPropsMetadata/impl-by-llms/mod.ts";
import {
  makeFinalResult as makeFinalResultBySet,
  parse as parseBySet,
} from "/Volumes/Tertiary/CodingProjects/Maintaining/kreantio/openfx-rs/crates/openfx/scripts/src/parsers/parser-ofxPropsBySet/impl-by-llms/mod.ts";
import { NameRegulator } from "/Volumes/Tertiary/CodingProjects/Maintaining/kreantio/openfx-rs/crates/openfx/scripts/src/utils/name-regulator.ts";

const INCLUDE_DIR =
  "/Volumes/Tertiary/CodingProjects/Maintaining/kreantio/openfx-rs/crates/openfx/vendor/openfx/openfx-cpp/include/openfx";

let failures = 0;
function check(label: string, condition: boolean) {
  if (!condition) failures++;
  console.log(`${condition ? "ok " : "FAIL"} ${label}`);
}

const metaHeader = await Deno.readTextFile(`${INCLUDE_DIR}/ofxPropsMetadata.h`);
const bySetHeader = await Deno.readTextFile(`${INCLUDE_DIR}/ofxPropsBySet.h`);

// --- metadata parser ---------------------------------------------------------
const metaResult = parse(metaHeader);
const metaFinal = makeFinalResult(metaResult);
const { assertions } = metaResult.propertyInfos;

check(
  "metadata: assertions keyed by constant value -> k-prefixed constant",
  assertions["OfxParamPropDefault"] === "kOfxParamPropDefault" &&
    assertions["OfxImageEffectPropPixelAspectRatio"] ===
      "kOfxImageEffectPropProjectPixelAspectRatio",
);
const map = metaFinal.keyConstantToCanonicalNameMap;
check(
  "metadata: final map strips the k prefix, keys unchanged",
  Object.keys(map).length === Object.keys(assertions).length &&
    Object.entries(assertions).every(([v, c]) => map[v] === c.slice(1)),
);
check(
  "metadata: user example OfxFieldNone -> OfxImageFieldNone",
  map["OfxFieldNone"] === "OfxImageFieldNone",
);

// --- bySet parser ------------------------------------------------------------
const bySetResult = parseBySet(bySetHeader);
const bySetFinal = makeFinalResultBySet(bySetResult);
const bySetMap = bySetFinal.keyConstantToCanonicalNameMap;
check(
  "bySet: final map strips the k prefix, keys unchanged",
  Object.keys(bySetMap).length ===
    Object.keys(bySetResult.infos.assertions).length &&
    Object.entries(bySetResult.infos.assertions).every(
      ([v, c]) => bySetMap[v] === c.slice(1),
    ),
);

// --- NameRegulator end-to-end -------------------------------------------------
new NameRegulator({ propsMetadata: metaFinal, propsBySet: bySetFinal });
console.log("done: NameRegulator constructed without duplicate-constant error");

if (failures > 0) {
  console.log(`\n${failures} check(s) FAILED`);
  Deno.exit(1);
}
console.log("\nall checks passed");
